@Component("appliedFee-handler")
@ProcessingGroup("appliedFee-processing-group")
public class AppliedFeeEventHandler {
	
	// core constructor
	AppliedFeeEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAppliedFeeEvent
     */
    @EventHandler
    public void handle( CreateAppliedFeeEvent event) {
        entityManager.persist(new AppliedFee(event.getAppliedFeeId(), event.getAmount(), event.getDescription(), event.getPaymentOrder(), event.getTransaction(), event.getFeeType()));
    }

    /*
     * @param	event UpdateAppliedFeeEvent
     */
    @EventHandler
    public AppliedFee handle( UpdateAppliedFeeEvent event) {
    	entityManager.merge(new AppliedFee(event.getAppliedFeeId(), event.getAmount(), event.getDescription(), event.getPaymentOrder(), event.getTransaction(), event.getFeeType()));
    }
    
    /*
     * @param	event DeleteAppliedFeeEvent
     */
    @EventHandler
    public void on( DeleteAppliedFeeEvent event) {
    	AppliedFee entity = new AppliedFee();
   
    	// ------------------------------------------
    	// apply the AppliedFeeId
    	// ------------------------------------------
    	entity.setAppliedFeeId( event.getAppliedFeeId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AppliedFeeRepository appliedFeeEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AppliedFeeEventHandler.class.getName());

}
